# Generated by build.py from recipe.yml for recipe ldap-provision-a-user-and-bind-as-it. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/ldap', 'partial/.surl/ldap' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/ldap/directory.ldif'), "dn: dc=example,dc=com`nobjectClass: domain`ndc: example`n`ndn: ou=people,dc=example,dc=com`nobjectClass: organizationalUnit`nou: people`n`ndn: uid=alice,ou=people,dc=example,dc=com`nobjectClass: inetOrgPerson`nuid: alice`ncn: Alice Liddell`nsn: Liddell`nmail: alice@example.com`n")
[IO.File]::WriteAllText((Join-Path $PWD 'partial/.surl/ldap/directory.ldif'), "dn: dc=example,dc=com`nobjectClass: domain`ndc: example`n`ndn: ou=people,dc=example,dc=com`nobjectClass: organizationalUnit`nou: people`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bob.ldif'), "dn: uid=bob,ou=people,dc=example,dc=com`nobjectClass: inetOrgPerson`nuid: bob`ncn: Bob Jones`nsn: Jones`nmail: bob@example.com`nuserPassword: b0b-pass`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bob.json'), "{`"user`":`"bob`",`"password`":`"b0b-pass`"}")
[IO.File]::WriteAllText((Join-Path $PWD 'control-token.txt'), "control-token-0123456789abcdefghij`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-plaintext-auth', '--user', 'tester:t3st-pass', '--control', 'http://127.0.0.1:8081', '--control-token-file', 'control-token.txt', 'ldap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{response_code}\n" -H "Authorization: Bearer control-token-0123456789abcdefghij" -H "Content-Type: text/plain" --data-binary @bob.ldif http://127.0.0.1:8081/v1/directory --next -s -o NUL -w "%{response_code}\n" -H "Authorization: Bearer control-token-0123456789abcdefghij" --json @bob.json http://127.0.0.1:8081/v1/accounts --next -s -u tester:t3st-pass "ldap://127.0.0.1:8080/ou=people,dc=example,dc=com?cn,mail?sub?(uid=bob)" --next -s -u "uid=bob,ou=people,dc=example,dc=com:b0b-pass" "ldap://127.0.0.1:8080/uid=bob,ou=people,dc=example,dc=com?uid?base" } finally { Stop-Process $server0 }
